using System.Linq.Expressions;
using Microsoft.EntityFrameworkCore;
using ShopApi.Common;
using ShopApi.Data;
using ShopApi.Models;

namespace ShopApi.Repositories;

/// <summary>Keeps customers in the database with Entity Framework Core.</summary>
public sealed class EfCustomerRepository(AppDbContext database) : ICustomerRepository
{
    public async Task<ListResult<Customer>> ListAsync(ListQuery query)
    {
        IQueryable<Customer> items = database.Customers;
        foreach (var (field, value) in query.Filters)
        {
            items = field switch
            {
                "id" => items.Where(item => item.Id == (long)value),
                "name" => items.Where(item => item.Name == (string?)value),
                "email" => items.Where(item => item.Email == (string?)value),
                "password" => items.Where(item => item.Password == (string?)value),
                "phone" => items.Where(item => item.Phone == (string?)value),
                "createdAt" => items.Where(item => item.CreatedAt == (DateTimeOffset?)value),
                _ => items,
            };
        }
        var total = await items.LongCountAsync();
        items = query.SortField switch
        {
            "id" => query.Descending ? items.OrderByDescending(item => item.Id) : items.OrderBy(item => item.Id),
            "name" => Sorted(items, item => item.Name, query.Descending),
            "email" => Sorted(items, item => item.Email, query.Descending),
            "password" => Sorted(items, item => item.Password, query.Descending),
            "phone" => Sorted(items, item => item.Phone, query.Descending),
            "createdAt" => Sorted(items, item => item.CreatedAt, query.Descending),
            _ => items.OrderBy(item => item.Id),
        };
        items = items.Skip(query.Offset);
        if (query.Limit is { } limit)
        {
            items = items.Take(limit);
        }
        return new ListResult<Customer>(await items.AsNoTracking().ToListAsync(), total);
    }

    public async Task<Customer?> GetAsync(long key) => await database.Customers.FindAsync(key);

    public async Task<Customer> AddAsync(Customer item)
    {
        database.Customers.Add(item);
        await database.SaveChangesAsync();
        // Read back, so the answer has what the database keeps
        await database.Entry(item).ReloadAsync();
        return item;
    }

    public async Task<Customer> UpdateAsync(Customer item)
    {
        await database.SaveChangesAsync();
        await database.Entry(item).ReloadAsync();
        return item;
    }

    public async Task DeleteAsync(long key) =>
        await database.Customers.Where(item => item.Id == key).ExecuteDeleteAsync();

    /// <summary>Sorts by a field: items without a value go last, whatever the order, and the key breaks ties.</summary>
    private static IQueryable<Customer> Sorted<TValue>(IQueryable<Customer> items, Expression<Func<Customer, TValue>> value, bool descending)
    {
        var missing = Expression.Lambda<Func<Customer, bool>>(
            Expression.Equal(value.Body, Expression.Constant(null, typeof(TValue))), value.Parameters);
        var ordered = items.OrderBy(missing);
        return (descending ? ordered.ThenByDescending(value) : ordered.ThenBy(value)).ThenBy(item => item.Id);
    }
}

